ALTER TABLE users ADD COLUMN security_version INT NOT NULL DEFAULT 0;
CREATE TABLE auth_refresh_sessions(token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,family_id CHAR(36) NOT NULL,expires_at DATETIME(3) NOT NULL,used_at DATETIME(3),revoked_at DATETIME(3),replacement_hash CHAR(64),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_secure_refresh_family(family_id),INDEX ix_secure_refresh_user(user_id),INDEX ix_secure_refresh_expiry(expires_at),CONSTRAINT fk_secure_refresh_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE security_audit(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,event_type VARCHAR(60) NOT NULL,outcome VARCHAR(30) NOT NULL,request_id VARCHAR(64),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_security_audit_user(user_id,created_at));
CREATE TABLE auth_password_resets(identifier_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL,attempts INT NOT NULL DEFAULT 0,expires_at DATETIME(3) NOT NULL,consumed_at DATETIME(3),CONSTRAINT fk_secure_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE auth_qr_sessions(qr_token VARCHAR(64) PRIMARY KEY,poll_hash CHAR(64) NOT NULL,user_id BIGINT UNSIGNED,expires_at DATETIME(3) NOT NULL,consumed_at DATETIME(3),confirmed_at DATETIME(3),INDEX ix_secure_qr_expiry(expires_at));
